from pathlib import Path
root=Path(__file__).resolve().parents[2]
def inject(file,old,new):
 p=root/file;s=p.read_text()
 if new in s:return
 assert s.count(old)==1,(file,old,s.count(old))
 p.write_text(s.replace(old,new))
